import{c as t,Q as o,j as r,m as n}from"./chunks/framework.DoOjWOm2.js";const p=JSON.parse('{"title":"Windows Desktop App","description":"","frontmatter":{},"headers":[],"relativePath":"clients/windows.md","filePath":"clients/windows.md"}'),a={name:"clients/windows.md"};function s(i,e,l,c,d,h){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="windows-desktop-app" tabindex="-1">Windows Desktop App <a class="header-anchor" href="#windows-desktop-app" aria-label="Permalink to &quot;Windows Desktop App&quot;">​</a></h1><p><strong>Phase:</strong> N (End-User Documentation) <strong>Step:</strong> N.13 <strong>Since:</strong> 0.18.0</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>The Phlix Windows app is a full-featured Electron desktop client with system tray integration and media key support. Download the installer, run it, enter your server URL, and start streaming. No admin privileges required for per-user installs.</p></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Hub-mode support (connecting to a Phlix Hub and auto-discovering servers) is planned for a future release. Currently, the Windows app connects directly to a server URL. Hub connection features will be documented once the feature is released.</p></div><h2 id="install-store-links" tabindex="-1">Install / Store Links <a class="header-anchor" href="#install-store-links" aria-label="Permalink to &quot;Install / Store Links&quot;">​</a></h2><ul><li><strong>Installer (.exe):</strong> <a href="https://github.com/detain/phlix-windows-client/releases" target="_blank" rel="noreferrer">github.com/detain/phlix-windows-client/releases</a> — download the latest <code>.exe</code> installer</li><li><strong>System requirements:</strong> Windows 10 (version 1903+) or Windows 11; 4 GB RAM; graphics acceleration recommended for smooth playback</li></ul><p>The installer handles the Visual C++ runtime dependency automatically. Auto-update is built in — the app checks for new releases on launch and prompts you to install.</p><h2 id="platform-specific-install-steps" tabindex="-1">Platform-Specific Install Steps <a class="header-anchor" href="#platform-specific-install-steps" aria-label="Permalink to &quot;Platform-Specific Install Steps&quot;">​</a></h2><ol><li>Download the latest <code>.exe</code> installer from the <a href="https://github.com/detain/phlix-windows-client/releases" target="_blank" rel="noreferrer">releases page</a>.</li><li>Run the installer: <ul><li><strong>Per-user install (recommended):</strong> Defaults to <code>%LOCALAPPDATA%\\Phlix</code> — no administrator privileges required.</li><li><strong>System-wide install:</strong> Choose &quot;Install for all users&quot; and grant admin elevation when prompted.</li></ul></li><li>Launch <strong>Phlix</strong> from the <strong>Start Menu</strong> or the desktop shortcut.</li><li>The system tray icon appears in the bottom-right corner — the app runs in the tray by default. Right-click for quick controls: <strong>Open</strong>, <strong>Play/Pause</strong>, <strong>Next</strong>, and <strong>Quit</strong>.</li></ol><h2 id="setup-steps" tabindex="-1">Setup Steps <a class="header-anchor" href="#setup-steps" aria-label="Permalink to &quot;Setup Steps&quot;">​</a></h2><h3 id="first-launch-—-direct-mode" tabindex="-1">First Launch — Direct Mode <a class="header-anchor" href="#first-launch-—-direct-mode" aria-label="Permalink to &quot;First Launch — Direct Mode&quot;">​</a></h3><p>On first launch, the app prompts you to connect to a server:</p><ol><li>Enter your server URL: <ul><li><strong>Local:</strong> <code>http://localhost:32400</code> (same machine) or <code>http://192.168.1.100:32400</code> (LAN IP)</li><li><strong>Remote:</strong> your server&#39;s public domain</li></ul></li><li>Click <strong>Connect</strong>.</li><li>Enter your server username and password.</li></ol><p>The URL and credentials are stored securely in the Windows Credential Manager.</p><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><ul><li><strong>Server:</strong> Update the direct server URL in <strong>Settings → Server → Server URL</strong></li><li><strong>Startup:</strong> Enable <strong>Settings → Startup → Launch on Windows logon</strong> to start the app minimized to the system tray automatically</li><li><strong>Playback:</strong> Adjust default quality, subtitle language, and audio track preferences in <strong>Settings → Playback</strong></li></ul><h2 id="hub-connection" tabindex="-1">Hub Connection <a class="header-anchor" href="#hub-connection" aria-label="Permalink to &quot;Hub Connection&quot;">​</a></h2><blockquote><p><strong>Note:</strong> Hub-mode support is under development. This section will be updated once the feature is released. To connect remotely without hub-mode, use your server&#39;s public URL directly or set up a Tailscale VPN.</p></blockquote><p>When hub-mode is available, you will be able to:</p><ol><li>Open <strong>Settings → Hub → Enable Hub Connection</strong>.</li><li>Enter your Hub URL (e.g., <code>https://hub.phlix.example.com</code>).</li><li>Authenticate with your Hub credentials.</li><li>Your server will be auto-discovered from your Hub account.</li></ol><h2 id="what-can-go-wrong" tabindex="-1">What Can Go Wrong <a class="header-anchor" href="#what-can-go-wrong" aria-label="Permalink to &quot;What Can Go Wrong&quot;">​</a></h2><h3 id="app-does-not-launch-missing-vc-runtime" tabindex="-1">App does not launch (missing VC++ runtime) <a class="header-anchor" href="#app-does-not-launch-missing-vc-runtime" aria-label="Permalink to &quot;App does not launch (missing VC++ runtime)&quot;">​</a></h3><p><strong>Symptom:</strong> Phlix crashes immediately on launch, or a dialog appears stating &quot;VCRUNTIME140.dll not found.&quot;</p><p><strong>Fix:</strong> Install the Visual C++ 2015–2022 Redistributable from <a href="https://aka.ms/vs/17/release/vc_redist.x64.exe" target="_blank" rel="noreferrer">Microsoft&#39;s official page</a>. The link is also in the release notes on the <a href="https://github.com/detain/phlix-windows-client/releases" target="_blank" rel="noreferrer">releases page</a>. Restart the app after installation.</p><h3 id="port-32400-blocked-by-firewall" tabindex="-1">Port 32400 blocked by firewall <a class="header-anchor" href="#port-32400-blocked-by-firewall" aria-label="Permalink to &quot;Port 32400 blocked by firewall&quot;">​</a></h3><p><strong>Symptom:</strong> The app shows &quot;Connection refused&quot; or &quot;Server unreachable&quot; when connecting to a local server, even though the server is running.</p><p><strong>Fix:</strong> Windows Defender Firewall is blocking the connection. Either add an inbound rule for <code>phlix-server.exe</code> in <strong>Windows Defender Firewall → Allow an app</strong>, or run the server once as Administrator to trigger the Windows firewall dialog. Ensure the rule allows TCP port 32400.</p><h3 id="hub-relay-not-working-network-issue" tabindex="-1">Hub relay not working (network issue) <a class="header-anchor" href="#hub-relay-not-working-network-issue" aria-label="Permalink to &quot;Hub relay not working (network issue)&quot;">​</a></h3><p><strong>Symptom:</strong> Local LAN connection works, but remote access via Hub relay fails — the app spins or shows &quot;Connection error&quot; when away from home.</p><p><strong>Fix:</strong> Verify both the client machine and the server have working internet connectivity. Check that your network does not block WebSocket connections (<code>ws://</code> or <code>wss://</code>) — common on coffee shop and enterprise networks. Try a different network (e.g., your phone&#39;s hotspot) to isolate whether the issue is network-specific. Also confirm the Hub relay URL is accessible from outside your network.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./mobile.html">Mobile app</a> — iOS and Android</li><li><a href="./web.html">Web client</a> — browser-based access without installing software</li><li><a href="./../advanced/hardware-transcoding.html">Hardware transcoding</a> — GPU acceleration on Windows for smooth 4K playback</li></ul>',32)])])}const g=t(a,[["render",s]]);export{p as __pageData,g as default};
